// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.DndModeimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — DnD Handler (Module 10 v2 — Step 10.9). * * Sets Do Not Disturb mode via `NotificationManager.setInterruptionFilter`. * * ## Modes (per [DndMode]) * *  - `NONE` — all notifications suppressed. *  - `PRIORITY` — only priority interruptions. *  - `ALARMS` — only alarms. *  - `ALL` — DnD off (all notifications allowed). * * ## Permission * * Requires `ACCESS_NOTIFICATION_POLICY` (Do Not Disturb access). Without it, * `setInterruptionFilter` silently fails. The handler checks [DnDService.hasDndAccess] * first and returns `Permission.SpecialAccessRequired` pointing to * `ACTION_NOTIFICATION_POLICY_ACCESS_SETTINGS` if missing. * * ## Idempotent execution (Review 2 Elite 1) * * If DnD is already in the target mode, skip the call. * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous DnD mode. Undo restores the actual previous mode. * * ## Resource category * * DnD uses [ResourceCategory.AUDIO] — same as ringer (both affect audio policy). * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Scope — DnD</a> */class DnDHandler(    private val dndService: DnDService,) : ReversibleHandler<SystemOperation.SetDndMode> {    override val id: String = "dnd"    override val displayName: String = "Do Not Disturb Control"    override val requiredPermissions: Set<String> = emptySet()  // ACCESS_NOTIFICATION_POLICY checked at runtime    override val resourceCategory: ResourceCategory = ResourceCategory.AUDIO    override fun isAvailable(): Boolean = true    override suspend fun execute(operation: SystemOperation.SetDndMode): Result<Unit> {        // Check DnD access first.        if (!dndService.hasDndAccess()) {            return Result.Failure(                error = AppError.Permission.SpecialAccessRequired(                    settingsIntent = android.provider.Settings.ACTION_NOTIFICATION_POLICY_ACCESS_SETTINGS,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        val success = dndService.setMode(operation.mode)        return if (success) {            Result.Success(Unit, CorrelationId.generate(), 0)        } else {            Result.Failure(                error = AppError.Hardware.Unknown("dnd"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    override suspend fun capturePreState(operation: SystemOperation.SetDndMode): Any? {        return try {            DndPreState(previousMode = dndService.getMode())        } catch (t: Throwable) {            Timber.tag("DndHandler").w("capturePreState failed", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetDndMode, preState: Any?) {        if (preState !is DndPreState) return        try {            dndService.setMode(preState.previousMode)        } catch (t: Throwable) {            Timber.tag("DndHandler").w("restorePreState failed", t)        }    }    override suspend fun getCurrentState(): Any? = try {        DndPreState(previousMode = dndService.getMode())    } catch (t: Throwable) { null }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetDndMode): Boolean {        return try {            dndService.getMode() == operation.mode        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetDndMode): String =        when (operation.mode) {            DndMode.NONE -> "DnD set to total silence"            DndMode.PRIORITY -> "DnD set to priority only"            DndMode.ALARMS -> "DnD set to alarms only"            DndMode.ALL -> "DnD turned off"        }    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is DndPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"DndPreState\",\"previousMode\":\"${preState.previousMode.name}\"}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "DndPreState" -> DndPreState(                previousMode = DndMode.valueOf((map["previousMode"] as? String) ?: "ALL"),            )            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for DnD (previous mode). */    data class DndPreState(val previousMode: DndMode)}
